fn local(name: &str) -> TracingConfig {
    TracingConfig::new(name).with_set_global(false)
}

async fn span_in(handle: &sdk::tracing::TracingHandle, name: &'static str, attrs: Vec<KeyValue>) {
    let mut opts = SpanOptions::default().tracer(handle.tracer("t", None));
    opts.attributes = attrs;
    with_span(name, opts, async { Ok::<_, Error>(()) })
        .await
        .unwrap();
}

